/**
 * DEMO catalog: types and helpers shared by server and client components.
 * The data comes from the image service (`/catalog/index.json`), generated by
 * `npm run catalog:import`. Everything here is temporary test data: not for sale,
 * synthetic prices, no material / gemstone / size claims.
 */
import { IMAGE_URL } from "./media";

export type DemoCategoryCode = "rings" | "earrings" | "necklaces" | "sets";

export interface DemoImage {
  asset: string;
  role: "primary" | "gallery";
  order: number;
  alt: string;
  width: number;
  height: number;
}

export interface DemoProduct {
  id: string;
  slug: string;
  status: "demo";
  kind: "catalog";
  category: DemoCategoryCode;
  title: string;
  tags: string[];
  description: null;
  material: null;
  gemstone: null;
  sizes: null;
  price: { amount: number; currency: "PKR"; synthetic: true };
  availability: "not-for-sale";
  images: DemoImage[];
  /** Internal review notes (e.g. image flagged for replacement). Optional for older catalogs. */
  reviewNotes?: string[];
}

export interface DemoCatalog {
  schema: "thegemsutra.catalog";
  schemaVersion: 1;
  dataset: string;
  environment: "demo";
  version: string;
  categories: { code: DemoCategoryCode; label: string }[];
  products: DemoProduct[];
}

export const DEMO_CATEGORY_LABEL: Record<DemoCategoryCode, string> = {
  rings: "Rings",
  earrings: "Earrings",
  necklaces: "Necklaces & Pendants",
  sets: "Bridal Sets",
};
export const DEMO_CATEGORIES = Object.keys(DEMO_CATEGORY_LABEL) as DemoCategoryCode[];

/** Visual filter vocabulary (mirrors services/image/src/catalog/schema.ts). */
export const DEMO_TAG_GROUPS = {
  colour: ["blue", "aqua", "red", "green", "purple", "pink", "white", "champagne", "multi"],
  shape: ["round", "oval", "pear", "heart", "marquise", "cushion", "rectangular", "teardrop", "circle", "crescent", "geometric"],
  style: ["halo", "solitaire", "three-stone", "split-shank", "twisted", "floral", "leaf", "hoop", "drop", "stud", "spiral", "pendant", "station", "layered", "choker", "collar", "bar", "statement", "minimal", "vintage", "bridal"],
} as const;
export type DemoTagGroup = keyof typeof DEMO_TAG_GROUPS;
export const DEMO_TAG_GROUP_LABEL: Record<DemoTagGroup, string> = { colour: "Colour", shape: "Shape", style: "Style" };

export const DEMO_BASE = "/demo/catalog";
export const demoCategoryPath = (c: DemoCategoryCode) => `${DEMO_BASE}/${c}`;
export const demoProductPath = (p: Pick<DemoProduct, "slug">) => `${DEMO_BASE}/item/${p.slug}`;

export function demoImageUrl(asset: string, variant: "card" | "full", width: number): string {
  return `${IMAGE_URL}/catalog/img/${asset}/${variant}.webp?w=${width}`;
}

export function demoSrcSet(asset: string, variant: "card" | "full", widths: number[]): string {
  return widths.map((w) => `${demoImageUrl(asset, variant, w)} ${w}w`).join(", ");
}

/**
 * Gallery images in display order, each genuine image once (an asset listed twice is
 * shown once). Never adds images: a one-photo product has a one-image gallery.
 */
export function galleryImages(images: DemoImage[]): DemoImage[] {
  const seen = new Set<string>();
  return [...images]
    .sort((a, b) => a.order - b.order)
    .filter((im) => (seen.has(im.asset) ? false : (seen.add(im.asset), true)));
}

/** Thumbnails and previous/next controls only make sense with more than one image. */
export const galleryHasNavigation = (count: number) => count > 1;

/** Next index when stepping through a gallery (wraps around; stays put for 0-1 images). */
export function galleryStep(index: number, delta: number, count: number): number {
  if (count <= 1) return 0;
  return (((index + delta) % count) + count) % count;
}

export const primaryImage = (p: DemoProduct) => galleryImages(p.images)[0];

/** Same category first, ranked by shared tags; then fill from other categories. */
export function relatedProducts(all: DemoProduct[], product: DemoProduct, limit = 4): DemoProduct[] {
  const score = (o: DemoProduct) => (o.category === product.category ? 100 : 0) + o.tags.filter((t) => product.tags.includes(t)).length;
  return all
    .filter((o) => o.id !== product.id)
    .map((o, i) => ({ o, s: score(o), i }))
    .sort((a, b) => b.s - a.s || a.i - b.i)
    .slice(0, limit)
    .map((x) => x.o);
}

export interface DemoFilters {
  q: string;
  colour: string[];
  shape: string[];
  style: string[];
  sort: "featured" | "price-asc" | "price-desc" | "name";
}

export function filterProducts(products: DemoProduct[], f: DemoFilters): DemoProduct[] {
  const q = f.q.trim().toLowerCase();
  const words = q ? q.split(/\s+/) : [];
  const out = products.filter((p) => {
    const hay = `${p.title} ${p.tags.join(" ")} ${DEMO_CATEGORY_LABEL[p.category]} ${p.id}`.toLowerCase();
    if (words.some((w) => !hay.includes(w))) return false;
    for (const g of ["colour", "shape", "style"] as const) if (f[g].length && !f[g].some((t) => p.tags.includes(t))) return false;
    return true;
  });
  if (f.sort === "price-asc") out.sort((a, b) => a.price.amount - b.price.amount);
  else if (f.sort === "price-desc") out.sort((a, b) => b.price.amount - a.price.amount);
  else if (f.sort === "name") out.sort((a, b) => a.title.localeCompare(b.title));
  return out;
}

export function isDemoCatalogEnabled(): boolean {
  return process.env.NODE_ENV !== "production" || process.env.ENABLE_DEMO_CATALOG === "true";
}
